/**
 * TruthTag — Epistemic Truth & Provenance Visual Indicator (Phase 6B)
 *
 * Visually differentiates:
 * - OBSERVED: Real observed system execution state
 * - SIMULATED: Generated by physics simulator / digital twin
 * - PREDICTED: ML forecasting / probability model prediction
 * - INFERRED: Causal / agent reasoning deduction
 * - LEARNED: Empirical generalization from accumulated memory
 */
import React from 'react';
import { Eye, Cpu, Brain, GitCommit, Sparkles } from 'lucide-react';
import { TruthMode, truthColor } from '../../visual/tokens';

interface TruthTagProps {
  mode: TruthMode | string;
  showIcon?: boolean;
  size?: 'sm' | 'md';
  title?: string;
  className?: string;
}

const TRUTH_CONFIG: Record<string, { label: string; icon: React.ReactNode; tooltip: string }> = {
  OBSERVED: {
    label: 'OBSERVED',
    icon: <Eye size={10} />,
    tooltip: 'Direct telemetry / real execution observation',
  },
  SIMULATED: {
    label: 'SIMULATED',
    icon: <Cpu size={10} />,
    tooltip: 'Generated by digital twin / adversarial simulator',
  },
  PREDICTED: {
    label: 'PREDICTED',
    icon: <Brain size={10} />,
    tooltip: 'Machine learning model forecast / probability',
  },
  INFERRED: {
    label: 'INFERRED',
    icon: <GitCommit size={10} />,
    tooltip: 'Causal reasoning / graph deduction',
  },
  LEARNED: {
    label: 'LEARNED',
    icon: <Sparkles size={10} />,
    tooltip: 'Hindsight empirical generalization from prior episodes',
  },
};

export const TruthTag: React.FC<TruthTagProps> = ({
  mode,
  showIcon = true,
  size = 'md',
  title,
  className = '',
}) => {
  const normalized = (mode || 'OBSERVED').toUpperCase();
  const config = TRUTH_CONFIG[normalized] || {
    label: normalized,
    icon: <Eye size={10} />,
    tooltip: 'System truth state',
  };

  const isSmall = size === 'sm';
  const color = truthColor(normalized);

  return (
    <span
      className={`truth-tag ${normalized.toLowerCase()} ${className}`}
      title={title || config.tooltip}
      style={{
        padding: isSmall ? '1px 6px' : '2px 8px',
        fontSize: isSmall ? '8px' : '9px',
        display: 'inline-flex',
        alignItems: 'center',
        gap: '4px',
        color,
      }}
    >
      {showIcon && <span style={{ display: 'inline-flex', alignItems: 'center' }}>{config.icon}</span>}
      <span>{config.label}</span>
    </span>
  );
};
